<section class="clinical-section"><h2>Examens et résultats</h2><p>Les mesures enregistrées restent modifiables. L’heure du don confirmé reprend l’arrivée enregistrée.</p><div class="clinical-grid"><?php foreach ($participations as $p): if ($p['statut']!=='ARRIVEE') continue; $m=$medicalMap[$p['id']]??[]; ?><article class="clinical-card"><header><div><strong><?= e($p['nom']) ?></strong><small><?= e($p['code_confirmation']) ?></small></div><span class="pill"><?= e($m['decision']??'En attente') ?></span></header><p class="muted">Arrivée : <?= $p['arrivee_le']?e(date('d/m/Y à H:i',strtotime($p['arrivee_le']))):'Non enregistrée' ?><?php if ($m['examen_saisi_le']): ?> · Examen saisi le <?= e(date('d/m/Y à H:i',strtotime($m['examen_saisi_le']))) ?><?php endif; ?></p>
<details id="examen-<?= (int)$p['id'] ?>"><summary>Examen avant don</summary><form method="post" action="index.php?page=examen-sauver" data-validate="examen" class="compact-form"><input type="hidden" name="csrf" value="<?= e(jetonCsrf()) ?>"><input type="hidden" name="collecte_id" value="<?= (int)$detail['id'] ?>"><input type="hidden" name="participation_id" value="<?= (int)$p['id'] ?>"><div class="exam-grid"><?php foreach (['tension_systolique'=>['Tension systolique','mmHg'], 'tension_diastolique'=>['Tension diastolique','mmHg'],'pouls'=>['Pouls','/min'],'temperature_c'=>['Température','°C'],'hemoglobine_g_dl'=>['Hémoglobine','g/dL'],'poids_kg'=>['Poids','kg']] as $key=>[$label,$unit]): ?><div class="field"><label for="<?= e($key) ?>-<?= (int)$p['id'] ?>"><?= e($label) ?> (<?= e($unit) ?>)</label><input id="<?= e($key) ?>-<?= (int)$p['id'] ?>" name="<?= e($key) ?>" type="number" step="0.1" value="<?= e((string)($m[$key]??'')) ?>"></div><?php endforeach; ?></div><div class="field"><label>Décision du professionnel</label><select name="decision"><?php foreach (['EN_ATTENTE'=>'En attente','APTE'=>'Apte','AJOURNE'=>'Ajourné'] as $value=>$label): ?><option value="<?= e($value) ?>" <?= ($m['decision']??'EN_ATTENTE')===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><button class="button button-primary">Enregistrer l’examen</button></form></details>
