select></div><div class="field"><label>Date indiquée par le centre</label><input type="date" name="prochain_don_le" value="<?= e($m['prochain_don_le']??'') ?>"></div><button class="button button-primary">Enregistrer le résultat</button></form></details><?php endif; ?></article><?php endforeach; ?></div></section>
